def transform(grid):
    h = len(grid) // 4
    w = len(grid[0])
    priority = (4, 8, 2)
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            top = grid[r][c]
            if top != 0:
                row.append(top)
            else:
                values = [grid[layer * h + r][c] for layer in range(1, 4)]
                row.append(next((color for color in priority if color in values), 0))
        out.append(row)
    return out
